/**
 * PCA process monitor (Hotelling T² and SPE / Q statistic).
 *
 * The model is trained offline (scripts/train-pca.ts) on normal-operation data
 * generated by this engine with fixed seeds, and saved as pca-model.json.
 *
 * The monitor deliberately has NO fault classifier: it outputs anomaly scores,
 * whether each 99 % threshold is exceeded, and which variables contribute. It
 * never names a disturbance, an IDV id or a fault class.
 */

export interface PcaModel {
  format: 'pca-monitor/1';
  variables: string[];
  window: number;
  mean: number[];
  scale: number[];
  /** variables x k loadings (columns are principal directions) */
  loadings: number[][];
  /** eigenvalues of the retained components */
  eigenvalues: number[];
  allEigenvalues: number[];
  k: number;
  explainedVariance: number;
  confidence: number;
  t2Limit: number;
  speLimit: number;
  training: Record<string, unknown>;
}

export interface PcaContributor {
  signal: string;
  /** share of the dominant statistic, 0..1 */
  share: number;
  /** sign of the standardised deviation */
  direction: 'high' | 'low';
}

export interface PcaScore {
  t2: number;
  t2Limit: number;
  spe: number;
  speLimit: number;
  /** max(t2/t2Limit, spe/speLimit); > 1 means a threshold is exceeded */
  score: number;
  exceeded: { t2: boolean; spe: boolean; any: boolean };
  dominant: 'T2' | 'SPE';
  contributors: PcaContributor[];
}

/** Mean of the last `w` rows (fewer if not available). */
export function windowMean(rows: number[][], w: number): number[] | null {
  if (!rows.length) return null;
  const n = Math.min(w, rows.length);
  const p = rows[0].length;
  const out = new Array<number>(p).fill(0);
  for (let i = rows.length - n; i < rows.length; i++) for (let j = 0; j < p; j++) out[j] += rows[i][j];
  for (let j = 0; j < p; j++) out[j] /= n;
  return out;
}

export function scorePca(model: PcaModel, x: number[], topN = 3): PcaScore {
  const p = model.variables.length;
  const k = model.k;
  const z = new Array<number>(p);
  for (let j = 0; j < p; j++) z[j] = (x[j] - model.mean[j]) / model.scale[j];
  const t = new Array<number>(k).fill(0);
  for (let i = 0; i < k; i++) for (let j = 0; j < p; j++) t[i] += model.loadings[j][i] * z[j];
  let t2 = 0;
  for (let i = 0; i < k; i++) t2 += (t[i] * t[i]) / model.eigenvalues[i];
  const resid = new Array<number>(p);
  let spe = 0;
  for (let j = 0; j < p; j++) {
    let rec = 0;
    for (let i = 0; i < k; i++) rec += model.loadings[j][i] * t[i];
    resid[j] = z[j] - rec;
    spe += resid[j] * resid[j];
  }
  const rT = t2 / model.t2Limit;
  const rS = spe / model.speLimit;
  const dominant: 'T2' | 'SPE' = rS >= rT ? 'SPE' : 'T2';
  const contrib = new Array<number>(p);
  for (let j = 0; j < p; j++) {
    if (dominant === 'SPE') contrib[j] = resid[j] * resid[j];
    else {
      let c = 0;
      for (let i = 0; i < k; i++) c += model.loadings[j][i] * t[i] / model.eigenvalues[i];
      contrib[j] = Math.max(0, z[j] * c);
    }
  }
  const total = contrib.reduce((a, b) => a + b, 0) || 1;
  const contributors = model.variables
    .map((signal, j) => ({ signal, share: +(contrib[j] / total).toFixed(3), direction: (z[j] >= 0 ? 'high' : 'low') as 'high' | 'low' }))
    .sort((a, b) => b.share - a.share)
    .slice(0, topN);
  return {
    t2: +t2.toFixed(3),
    t2Limit: model.t2Limit,
    spe: +spe.toFixed(3),
    speLimit: model.speLimit,
    score: +Math.max(rT, rS).toFixed(3),
    exceeded: { t2: rT > 1, spe: rS > 1, any: rT > 1 || rS > 1 },
    dominant,
    contributors,
  };
}

/* ---------------------------- training helpers ---------------------------- */

/** Symmetric eigen-decomposition by cyclic Jacobi rotations. Returns values desc + column vectors. */
export function eigSym(A: number[][]): { values: number[]; vectors: number[][] } {
  const n = A.length;
  const a = A.map((r) => r.slice());
  const v: number[][] = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
  for (let sweep = 0; sweep < 100; sweep++) {
    let off = 0;
    for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) off += a[i][j] * a[i][j];
    if (off < 1e-22) break;
    for (let pI = 0; pI < n; pI++) {
      for (let q = pI + 1; q < n; q++) {
        if (Math.abs(a[pI][q]) < 1e-300) continue;
        const theta = (a[q][q] - a[pI][pI]) / (2 * a[pI][q]);
        const tt = Math.sign(theta || 1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
        const c = 1 / Math.sqrt(tt * tt + 1);
        const s = tt * c;
        for (let k = 0; k < n; k++) {
          const akp = a[k][pI];
          const akq = a[k][q];
          a[k][pI] = c * akp - s * akq;
          a[k][q] = s * akp + c * akq;
        }
        for (let k = 0; k < n; k++) {
          const apk = a[pI][k];
          const aqk = a[q][k];
          a[pI][k] = c * apk - s * aqk;
          a[q][k] = s * apk + c * aqk;
        }
        for (let k = 0; k < n; k++) {
          const vkp = v[k][pI];
          const vkq = v[k][q];
          v[k][pI] = c * vkp - s * vkq;
          v[k][q] = s * vkp + c * vkq;
        }
      }
    }
  }
  const idx = Array.from({ length: n }, (_, i) => i).sort((x, y) => a[y][y] - a[x][x]);
  return { values: idx.map((i) => a[i][i]), vectors: v.map((row) => idx.map((i) => row[i])) };
}

export function quantile(sorted: number[], q: number): number {
  if (!sorted.length) return NaN;
  const pos = (sorted.length - 1) * q;
  const lo = Math.floor(pos);
  const hi = Math.ceil(pos);
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
}

export interface FitOptions {
  variables: string[];
  window: number;
  varianceTarget: number;
  confidence: number;
  training: Record<string, unknown>;
}

/** Fit autoscaled PCA and set empirical T²/SPE limits at the given confidence. */
export function fitPca(rows: number[][], opt: FitOptions): PcaModel {
  const n = rows.length;
  const p = opt.variables.length;
  const mean = new Array<number>(p).fill(0);
  rows.forEach((r) => r.forEach((v, j) => { mean[j] += v / n; }));
  const scale = new Array<number>(p).fill(0);
  rows.forEach((r) => r.forEach((v, j) => { scale[j] += (v - mean[j]) ** 2 / (n - 1); }));
  for (let j = 0; j < p; j++) scale[j] = Math.sqrt(scale[j]) || 1;
  const Z = rows.map((r) => r.map((v, j) => (v - mean[j]) / scale[j]));
  const C: number[][] = Array.from({ length: p }, () => new Array<number>(p).fill(0));
  Z.forEach((z) => { for (let i = 0; i < p; i++) for (let j = 0; j < p; j++) C[i][j] += z[i] * z[j] / (n - 1); });
  const { values, vectors } = eigSym(C);
  const tot = values.reduce((a, b) => a + b, 0);
  let k = 0;
  let acc = 0;
  while (k < p && acc / tot < opt.varianceTarget) { acc += values[k]; k++; }
  k = Math.max(1, Math.min(p - 1, k));
  const loadings = vectors.map((row) => row.slice(0, k));
  const model: PcaModel = {
    format: 'pca-monitor/1',
    variables: opt.variables.slice(),
    window: opt.window,
    mean,
    scale,
    loadings,
    eigenvalues: values.slice(0, k),
    allEigenvalues: values,
    k,
    explainedVariance: values.slice(0, k).reduce((a, b) => a + b, 0) / tot,
    confidence: opt.confidence,
    t2Limit: 1,
    speLimit: 1,
    training: opt.training,
  };
  const t2s: number[] = [];
  const spes: number[] = [];
  rows.forEach((r) => { const s = scorePca(model, r); t2s.push(s.t2); spes.push(s.spe); });
  t2s.sort((a, b) => a - b);
  spes.sort((a, b) => a - b);
  model.t2Limit = +quantile(t2s, opt.confidence).toFixed(4);
  model.speLimit = +quantile(spes, opt.confidence).toFixed(4);
  return model;
}
